@GlobalTransactional
public OrderCreateResult createOrder(OrderCreateRequest request) {
    // 1. 校验商品库存
    inventoryService.checkStock(request.getItems());

    // 2. 扣减库存
    inventoryService.decreaseStock(request.getItems());

    // 3. 创建订单
    Order order = orderService.createOrder(request);

    // 4. 使用优惠券
    if (request.getCouponId() != null) {
        marketingService.useCoupon(request.getCouponId(), order.getId());
    }

    // 5. 发送延迟消息（15分钟后检查支付状态）
    rocketMQTemplate.asyncSend("order-check-topic", 
        MessageBuilder.withPayload(order.getId()).build(), 
        15, TimeUnit.MINUTES);

    return new OrderCreateResult(order.getId());
}
