@PostMapping("/seckill/{productId}")
public Result seckill(@PathVariable Long productId, @RequestHeader("Authorization") String token) {
    // 1. 获取用户信息
    User user = jwtUtil.parseToken(token);

    // 2. 限流检查
    if (!rateLimiter.tryAcquire()) {
        return Result.fail("系统繁忙，请稍后再试");
    }

    // 3. 检查是否已购买（幂等）
    String boughtKey = "seckill:bought:" + productId + ":" + user.getId();
    if (redisTemplate.hasKey(boughtKey)) {
        return Result.fail("您已参与过该活动");
    }

    // 4. Redis预减库存（Lua脚本保证原子性）
    String stockKey = "seckill:stock:" + productId;
    Long stock = redisTemplate.execute(SECKILL_SCRIPT, Collections.singletonList(stockKey));

    if (stock == null || stock < 0) {
        return Result.fail("商品已售罄");
    }

    // 5. 发送MQ异步创建订单
    SeckillMessage message = new SeckillMessage(user.getId(), productId);
    rocketMQTemplate.asyncSend("seckill-order-topic", message);

    return Result.success("抢购成功，正在生成订单");
}

// Lua脚本
private static final DefaultRedisScript<Long> SECKILL_SCRIPT = new DefaultRedisScript<>();
static {
    SECKILL_SCRIPT.setScriptText(
        "if (redis.call('exists', KEYS[1]) == 1) then" +
        "    local stock = tonumber(redis.call('get', KEYS[1]));" +
        "    if (stock > 0) then" +
        "        redis.call('decr', KEYS[1]);" +
        "        return stock - 1;" +
        "    end;" +
        "    return -1;" +
        "end;" +
        "return -1;"
    );
    SECKILL_SCRIPT.setResultType(Long.class);
}
