@Component
@RocketMQMessageListener(topic = "order-check-topic", consumerGroup = "order-check-consumer")
public class OrderCheckListener implements RocketMQListener<Long> {

    @Autowired
    private OrderService orderService;

    @Override
    public void onMessage(Long orderId) {
        Order order = orderService.getById(orderId);

        // 检查订单状态
        if (order != null && OrderStatus.UNPAID.equals(order.getStatus())) {
            // 取消订单
            orderService.cancelOrder(orderId);

            // 回滚库存
            inventoryService.rollbackStock(order.getItems());

            // 回滚优惠券
            if (order.getCouponId() != null) {
                marketingService.rollbackCoupon(order.getCouponId());
            }

            log.info("订单 {} 超时未支付，已自动取消", orderId);
        }
    }
}
