@Component
@ChannelHandler.Sharable
public class IMServerHandler extends SimpleChannelInboundHandler<TextWebSocketFrame> {

    private static final ConcurrentHashMap<String, Channel> userChannelMap = new ConcurrentHashMap<>();

    @Override
    protected void channelRead0(ChannelHandlerContext ctx, TextWebSocketFrame frame) {
        Message msg = JSON.parseObject(frame.text(), Message.class);

        switch (msg.getMsgType()) {
            case CONNECT:
                handleConnect(ctx, msg);
                break;
            case CHAT:
                handleChat(msg);
                break;
            case GROUP_CHAT:
                handleGroupChat(msg);
                break;
            case HEARTBEAT:
                ctx.writeAndFlush(new PongWebSocketFrame());
                break;
        }
    }

    private void handleChat(Message msg) {
        // 保存消息到MongoDB
        messageService.save(msg);

        // 推送给接收方
        Channel targetChannel = userChannelMap.get(msg.getToUserId());
        if (targetChannel != null && targetChannel.isActive()) {
            targetChannel.writeAndFlush(new TextWebSocketFrame(JSON.toJSONString(msg)));
        } else {
            // 用户离线，发送推送通知
            pushService.sendPush(msg.getToUserId(), "您有一条新消息");
        }
    }
}
