@Service
public class FeedService {

    // 大V阈值
    private static final int FAN_THRESHOLD = 10000;

    public void publishPost(Post post) {
        User author = userService.getById(post.getUserId());

        if (author.getFanCount() > FAN_THRESHOLD) {
            // 大V：写入帖子，粉丝拉取
            postService.save(post);
        } else {
            // 普通用户：推送到粉丝收件箱
            pushToFans(post);
        }
    }

    private void pushToFans(Post post) {
        List<Long> fanIds = fanService.getFanIds(post.getUserId());

        // 批量推送到粉丝收件箱（Redis ZSet）
        for (List<Long> batch : Lists.partition(fanIds, 1000)) {
            redisTemplate.executePipelined((RedisCallback<Object>) connection -> {
                for (Long fanId : batch) {
                    String inboxKey = "feed:inbox:" + fanId;
                    connection.zAdd(inboxKey.getBytes(), post.getCreateTime().getTime(), 
                        post.getId().toString().getBytes());
                }
                return null;
            });
        }
    }

    public List<Post> getFeed(Long userId, Long lastPostId) {
        // 从收件箱拉取
        String inboxKey = "feed:inbox:" + userId;
        Set<String> postIds = redisTemplate.opsForZSet()
            .reverseRangeByScore(inboxKey, 0, lastPostId != null ? lastPostId : Double.MAX_VALUE, 0, 20);

        if (postIds == null || postIds.isEmpty()) {
            // 收件箱为空，从关注的大V拉取
            return pullFromFollowings(userId);
        }

        return postService.listByIds(postIds);
    }
}
