public class RealtimeETLJob {
    public static void main(String[] args) throws Exception {
        StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setParallelism(4);

        // 从Kafka读取数据
        KafkaSource<String> source = KafkaSource.<String>builder()
            .setBootstrapServers("kafka:9092")
            .setTopics("order-topic")
            .setGroupId("flink-etl-group")
            .setStartingOffsets(OffsetsInitializer.latest())
            .setValueOnlyDeserializer(new SimpleStringSchema())
            .build();

        DataStream<Order> orders = env.fromSource(source, WatermarkStrategy.noWatermarks(), "Kafka Source")
            .map(json -> JSON.parseObject(json, Order.class));

        // 实时聚合：每5分钟统计各品类销售额
        DataStream<CategorySales> sales = orders
            .assignTimestampsAndWatermarks(WatermarkStrategy.<Order>forBoundedOutOfOrderness(Duration.ofSeconds(30))
                .withTimestampAssigner((order, timestamp) -> order.getCreateTime().getTime()))
            .keyBy(Order::getCategoryId)
            .window(TumblingEventTimeWindows.of(Time.minutes(5)))
            .aggregate(new SalesAggregateFunction());

        // 写入ClickHouse
        sales.addSink(new ClickHouseSink<>("jdbc:clickhouse://clickhouse:8123/default", 
            "INSERT INTO category_sales VALUES (?,?,?,?)"));

        env.execute("Realtime Sales ETL");
    }
}
